54: {id:'mira',name:'Mira',class:'Field Medic',icon:'✚',color:'#a77978',x:0,y:2,hp:21,maxHp:21,atk:4,def:2,move:4,range:1,team:'player',acted:false,moved:false,healer:true,desc:'A healer who keeps hope alive.'},
55: {id:'raider1',name:'Rook',class:'Bandit',icon:'⚔',color:'#9b5046',x:7,y:1,hp:21,maxHp:21,atk:7,def:2,move:4,range:1,team:'enemy',acted:false},
