59: let selected='alaric',inspectId='alaric',phase='player',gameOver=false,moveTiles=new Set(),targetTiles=new Set(),pendingMove=null,logEntries=[],turn=1;
60: const board=document.getElementById('board'), byId=id=>units.find(u=>u.id===id), alive=u=>u.hp>0, at=(x,y)=>units.find(u=>alive(u)&&u.x===x&&u.y===y), tileKey=(x,y)=>`${x},${y}`, dist=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
61: function terrainAt(x,y){return terrain[y][x]}function cost(x,y){return terrainAt(x,y)==='forest'?2:1}function defense(u){return terrainAt(u.x,u.y)==='fort'?2:terrainAt(u.x,u.y)==='forest'?1:0}
62: function addLog(text,type=''){logEntries.unshift({text,type});logEntries=logEntries.slice(0,9);renderLog()}
63: function renderLog(){document.getElementById('log').innerHTML=logEntries.map((e,i)=>`<p class="${i===0?'latest ':''}${e.type}">${e.text}</p>`).join('')}
64: function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1700)}
65: function rangeFrom(u,max,stopUnits=true){const seen=new Map([[tileKey(u.x,u.y),0]]),queue=[[u.x,u.y,0]];for(let i=0;i<queue.length;i++){const [x,y,c]=queue[i];for(const [dx,dy] of [[0,-1],[1,0],[0,1],[-1,0]]){const nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=W||ny>=H)continue;const nc=c+cost(nx,ny),key=tileKey(nx,ny);if(nc>max||(seen.has(key)&&seen.get(key)<=nc))continue;if(terrainAt(nx,ny)==='water'||(stopUnits&&at(nx,ny)&&!(nx===u.x&&ny===u.y)))continue;seen.set(key,nc);queue.push([nx,ny,nc])}}return seen}
66: function canHit(a,b){const d=dist(a,b);return d>=1&&d<=a.range}
67: function renderBoard(){board.innerHTML='';for(let y=0;y<H;y++)for(let x=0;x<W;x++){const t=document.createElement('div'),terrainName=terrainAt(x,y),u=at(x,y);t.className=`tile ${terrainName}`;t.dataset.x=x;t.dataset.y=y;t.setAttribute('role','gridcell');t.setAttribute('aria-label',`${String.fromCharCode(65+x)}${y+1} ${terrainName}${u?`, ${u.name}`:''}`);if(moveTiles.has(tileKey(x,y)))t.classList.add('range');if(targetTiles.has(tileKey(x,y)))t.classList.add('attack-range');if(pendingMove&&pendingMove.has(tileKey(x,y)))t.classList.add('path');if(selected&&byId(selected)?.x===x&&byId(selected)?.y===y)t.classList.add('selected');const coord=document.createElement('span');coord.className='coord';coord.textContent=`${String.fromCharCode(65+x)}${y+1}`;t.append(coord);if(u){const p=document.createElement('div');p.className=`piece ${u.team==='enemy'?'enemy':''} ${u.id===selected?'selected-piece':''} ${u.acted?'done':''}`;p.innerHTML=`<div class="sprite" style="--unit:${u.color}">${u.icon}</div><span class="unit-hp"><i style="width:${100*u.hp/u.maxHp}%"></i></span>`;t.append(p)}t.addEventListener('click',()=>onTile(x,y));board.append(t)}}
68: function renderRoster(){const list=document.getElementById('unitList'),party=units.filter(u=>u.team==='player');document.getElementById('rosterCount').textContent=`${party.filter(alive).length} / ${party.length} standing`;list.innerHTML=party.map(u=>`<div class="unit-row ${u.id===selected?'active':''} ${!alive(u)?'down':''}" data-id="${u.id}"><div class="unit-token" style="background:${u.color}">${u.icon}</div><div class="unit-meta"><strong>${u.name}</strong><small>${u.class}${u.acted&&alive(u)?' · acted':''}</small><div class="hp-track"><i style="width:${100*u.hp/u.maxHp}%;background:${u.hp/u.maxHp<.35?'#bd6557':''}"></i></div></div><span class="tiny-hp">${u.hp}/${u.maxHp}</span></div>`).join('');list.querySelectorAll('.unit-row').forEach(el=>el.addEventListener('click',()=>selectUnit(el.dataset.id)))}
69: function renderInspect(){const u=byId(inspectId)||byId(selected)||units[0],card=document.getElementById('inspectCard');if(!u)return;card.innerHTML=`<div class="inspect-header"><div class="portrait ${u.team==='enemy'?'enemy':''}" style="background:linear-gradient(145deg,${u.color},#303d35)">${u.icon}</div><div><div class="inspect-name">${u.name}</div><div class="inspect-class">${u.class}</div></div></div><div class="inspect-hp"><div class="hp-text"><span>Vitality</span><b>${u.hp} <span style="color:#a1a091;font-weight:400">/ ${u.maxHp}</span></b></div><div class="hpbar"><i style="width:${Math.max(0,100*u.hp/u.maxHp)}%;${u.hp/u.maxHp<.35?'background:linear-gradient(90deg,#b55d50,#d78469)':''}"></i></div></div><div class="stats"><div class="stat"><b>${u.atk}</b><small>Power</small></div><div class="stat"><b>${u.def}</b><small>Guard</small></div><div class="stat"><b>${u.move}</b><small>Move</small></div><div class="stat"><b>${u.range===1?'1':`1–${u.range}`}</b><small>Reach</small></div></div>`}
70: function renderPhase(){const enemy=phase==='enemy';document.getElementById('phaseText').textContent=enemy?'Bandit Phase':`Player Phase`;document.getElementById('phaseIcon').textContent=enemy?'☠':'⚔';document.getElementById('turnCard').classList.toggle('enemy',enemy);document.getElementById('endTurnBtn').textContent=enemy?'Bandits are moving…':`End Player Phase  →`;document.getElementById('endTurnBtn').disabled=enemy||gameOver}
71: function renderActions(){const u=byId(selected),ready=!!u&&alive(u)&&u.team==='player'&&phase==='player'&&!gameOver&&!u.acted;document.getElementById('attackBtn').disabled=!ready||!canAttackSome(u);document.getElementById('waitBtn').disabled=!ready;document.getElementById('healBtn').disabled=!ready||!u.healer||!adjacentInjured(u);document.getElementById('cancelBtn').disabled=!selected||phase!=='player'||gameOver}
72: function canAttackSome(u){return units.some(e=>alive(e)&&e.team==='enemy'&&canHit(u,e))}
73: function adjacentInjured(u){return units.some(a=>alive(a)&&a.team==='player'&&a.id!==u.id&&a.hp<a.maxHp&&dist(a,u)===1)}
74: function refresh(){renderBoard();renderRoster();renderInspect();renderPhase();renderActions()}
75: function selectUnit(id){const u=byId(id);if(!u||!alive(u))return;inspectId=id;if(u.team==='player'&&phase==='player'&&!u.acted){selected=id;pendingMove=null;moveTiles=u.moved?new Set():rangeFrom(u,u.move);targetTiles=new Set(units.filter(e=>alive(e)&&e.team==='enemy'&&canHit(u,e)).map(e=>tileKey(e.x,e.y)))}else{selected=u.team==='enemy'?selected:id;moveTiles.clear();targetTiles.clear()}refresh()}
76: function onTile(x,y){if(gameOver||phase!=='player')return;const u=at(x,y);if(u){inspectId=u.id;if(u.team==='player'){if(!u.acted){selectUnit(u.id);return}selected=u.id;moveTiles.clear();targetTiles.clear();refresh();return}if(selected){const actor=byId(selected);if(actor&&alive(actor)&&!actor.acted&&canHit(actor,u)){attack(actor,u);return}}refresh();return}const actor=byId(selected);if(!actor||!alive(actor)||actor.acted)return;const key=tileKey(x,y);if(moveTiles.has(key)){actor.x=x;actor.y=y;actor.moved=true;actor.acted=true;pendingMove=null;moveTiles.clear();targetTiles.clear();inspectId=actor.id;selected=actor.id;const hittable=units.some(e=>alive(e)&&e.team==='enemy'&&canHit(actor,e));if(hittable||(actor.healer&&adjacentInjured(actor))){actor.acted=false;targetTiles=new Set(units.filter(e=>alive(e)&&e.team==='enemy'&&canHit(actor,e)).map(e=>tileKey(e.x,e.y)));addLog(`<strong>${actor.name}</strong> moves. Choose an action, or Wait.`)}else addLog(`<strong>${actor.name}</strong> advances into position.`);refresh();return}if(actor.acted){moveTiles.clear();targetTiles.clear();refresh()}}
77: function attack(a,d){if(!canHit(a,d)){toast('Target is out of range');return}const terrainBonus=defense(d),damage=Math.max(1,a.atk-d.def-terrainBonus);d.hp=Math.max(0,d.hp-damage);a.acted=true;moveTiles.clear();targetTiles.clear();pendingMove=null;addLog(`<strong>${a.name}</strong> strikes ${d.name} for <strong>${damage}</strong> damage${d.hp===0?' — defeated!':''}.`,'combat');inspectId=d.hp===0?a.id:d.id;selected=a.id;refresh();if(d.hp===0)toast(`${d.name} has fallen`);checkEnd()}
78: function doWait(){const u=byId(selected);if(!u||u.acted)return;u.acted=true;moveTiles.clear();targetTiles.clear();addLog(`<strong>${u.name}</strong> holds position.`);refresh()}
