 function stopRing(){if(!ring||!ring.active||performance.now()<ring.started)return;ring.active=false;cancelAnimationFrame(ringFrame);const degree=((ring.angle%360)+360)%360;let result='miss';for(const z of ring.zones){const delta=Math.abs(((degree-z.center+540)%360)-180);if(delta<=z.strike/2){result='crit';break}if(delta<=z.hit/2)result='hit'}const panel=document.getElementById('ringPanel'),box=document.getElementById('ringResult');box.classList.add('show');panel.classList.remove('shake');void panel.offsetWidth;if(result==='miss'){panel.classList.add('shake');document.getElementById('ringResultTitle').textContent='MISS';document.getElementById('ringResultTitle').style.color='#d97967';document.getElementById('ringResultText').textContent='The blade slips past. Your chain ends.';document.getElementById('ringResultHint').textContent=ring.landed?`${ring.landed} strike${ring.landed===1?'':'s'} landed`:'No damage dealt';finishRingAttack(false);return}const tune=ringTuning[ring.level-1],base=Math.max(1,ring.actor.atk-ring.target.def-defense(ring.target)),damage=Math.max(1,Math.floor(base*tune.mult*(result==='crit'?1.5:1)));ring.damage+=damage;ring.landed++;document.getElementById('ringResultTitle').textContent=result==='crit'?'CRITICAL!':'STRIKE!';document.getElementById('ringResultTitle').style.color=result==='crit'?'#f0785f':'#efc771';document.getElementById('ringResultText').textContent=`${result==='crit'?'Critical ':''}+${damage} damage · chain ×${tune.mult.toFixed(2)}`;if(ring.level>=5){document.getElementById('ringResultHint').textContent='Maximum chain';finishRingAttack(true);return}document.getElementById('ringResultHint').textContent='Next ring incoming…';const next=ring.level+1;setTimeout(()=>{if(!ring)return;beginRingLevel(next)},620)}
